fmiModelDescription:
{%- if modelExchange %}

{%- endif %}

{%- if coSimulation %}

{%- endif %}










  {%- for input in inputs %}
  {%- for scalar in input.scalarValues %}
  <{{ input.vType.FMIType }} name="{{ scalar.name }}" valueReference="{{ scalar.valueReference }}" causality="{{ input.causality }}" variability="{{ input.variability }}"{% if input.initial %} initial="{{ input.initial }}"{% endif %} description="{%if scalar.label %}{{ scalar.label }}{% else %}{{ input.description }}{% endif %}" start="{{ scalar.start }}"/>
  {%- endfor %}
  {%- endfor %}
  {%- for output in outputs %}
  {%- for scalar in output.scalarValues %}
  <{{ output.vType.FMIType }} name="{{ scalar.name }}" valueReference="{{ scalar.valueReference }}" causality="{{ output.causality }}" variability="{{ output.variability }}"{% if output.initial %} initial="{{ output.initial }}"{% endif %}{% if scalar.stateValueReference is defined %} derivative="{{ scalar.stateValueReference }}"{% endif %} description="{%if scalar.label %}{{ scalar.label }}{% else %}{{ output.description }}{% endif %}"/>
  {%- endfor %}
  {%- endfor %}
  {#- Only an initial="exact" feedback state, which a master may set before
      the end of initialization, carries a start: FMI 3.0 forbids it on
      initial="calculated" variables. #}
  {%- for feedbackState in feedbackStates %}
  {%- for scalar in feedbackState.scalarValues %}
  <{{ feedbackState.vType.FMIType }} name="{{ scalar.name }}" valueReference="{{ scalar.valueReference }}" causality="{{ feedbackState.causality }}" variability="{{ feedbackState.variability }}" initial="{{ feedbackState.initial }}"{% if feedbackState.initial == "exact" %} start="{{ scalar.start }}"{% endif %} description="{%if scalar.label %}{{ scalar.label }}{% else %}{{ feedbackState.description }}{% endif %}"/>
  {%- endfor %}
  {%- endfor %}


{#- Co-Simulation runs the network only inside fmi3DoStep, so at a
    communication point its outputs depend on none of the knowns. An FMU
    that also supports Model Exchange keeps the default (no attribute,
    which means all knowns), because Model Exchange outputs depend on the
    inputs. #}
{%- set dependencies = ' dependencies=""' if coSimulation and not modelExchange else '' %}

  {%- for output in outputs %}
  {%- if not output.derivativeOf %}
  {%- for scalar in output.scalarValues %}

  {%- endfor %}
  {%- endif %}
  {%- endfor %}
  {%- for input in inputs %}
  {%- if input.isContinuousState %}
  {%- for scalar in input.scalarValues %}

  {%- endfor %}
  {%- endif %}
  {%- endfor %}
  {%- for output in outputs %}
  {%- if output.derivativeOf %}
  {%- for scalar in output.scalarValues %}

  {%- endfor %}
  {%- endif %}
  {%- endfor %}
  {%- for output in outputs %}
  {%- for scalar in output.scalarValues %}

  {%- endfor %}
  {%- endfor %}
